css:
.lsm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsm-root,.lsm-root *,.lsm-root *::before,.lsm-root *::after{box-sizing:border-box}
.lsm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsm-root img{display:block;border:0;max-width:none}
.lsm-root [hidden]{display:none!important}
.lsm-root .n17_181{grid-column:1;align-content:stretch;display:flex;align-items:center;justify-content:space-between;justify-self:stretch;padding-left:8px;padding-right:8px;position:relative;border-radius:3px;grid-row:5;align-self:stretch;flex-shrink:0;border-style:solid;border-color:var(--wa-point, #6e8ab8);border-width:1px;background-image:linear-gradient(35.097481953110446deg, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 23.926%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 5.1%, transparent) 45.794%, color-mix(in srgb, var(--wa-bg, rgb(235 235 235)) 0%, transparent) 46.766%, color-mix(in srgb, var(--wa-surface, rgb(124 124 124)) 0%, transparent) 72.521%), linear-gradient(90deg, color-mix(in srgb, var(--wa-surface, rgb(40 40 40)) 75%, transparent) 0%, color-mix(in srgb, var(--wa-surface, rgb(40 40 40)) 75%, transparent) 100%)}
.lsm-root .n17_182{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #b3b4c1);font-size:12px;white-space:nowrap;width:22px}
.lsm-root .n17_183{position:relative;flex-shrink:0;width:12px;height:12px}
.lsm-root .x59{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsm-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsm-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsm-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsm-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsm-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsm-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsm-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsm-root[data-theme="light"] .n17_181{border-color:var(--wa-line, #8498b9);background-image:linear-gradient(35.097481953110446deg, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 0%, transparent) 23.926%, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 5.1%, transparent) 45.794%, color-mix(in srgb, var(--wa-surface, rgb(102 107 117)) 0%, transparent) 46.766%, color-mix(in srgb, var(--wa-surface, rgb(173 177 184)) 0%, transparent) 72.521%), linear-gradient(90deg, color-mix(in srgb, var(--wa-bg, rgb(228 230 232)) 75%, transparent) 0%, color-mix(in srgb, var(--wa-bg, rgb(228 230 232)) 75%, transparent) 100%)}
.lsm-root[data-theme="light"] .n17_182{color:var(--wa-text-sub, #454950)}
